const input = $input.first().json;
const body = input.body || input;
const query = input.query || {};

// Accept from body or query
const recipeId = body.recipe_id || query.recipe_id;
const commentId = body.comment_id || query.comment_id;
const discordUserId = body.discord_user_id || query.discord_user_id;

const errors = [];
if (!recipeId) errors.push('recipe_id');
if (!commentId) errors.push('comment_id');
if (!discordUserId) errors.push('discord_user_id');

if (errors.length > 0) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: `Parametres requis manquants: ${errors.join(', ')}`,
        status: 'BAD_REQUEST'
      }
    }
  }];
}

return [{
  json: {
    valid: true,
    recipe_id: recipeId,
    comment_id: commentId,
    discord_user_id: discordUserId
  }
}];

const apiResponse = $input.first().json;
const inputData = $('Validate Input').first().json;

const statusCode = apiResponse.statusCode || 200;
const body = apiResponse.body || apiResponse;

if (statusCode === 403) {
  return [{
    json: {
      success: false,
      error: {
        code: 403,
        message: 'Non autorise: vous ne pouvez supprimer que vos propres commentaires',
        status: 'FORBIDDEN'
      }
    }
  }];
}

if (statusCode === 404) {
  return [{
    json: {
      success: false,
      error: {
        code: 404,
        message: `Commentaire '${inputData.comment_id}' non trouve`,
        status: 'NOT_FOUND'
      }
    }
  }];
}

if (statusCode >= 400) {
  return [{
    json: {
      success: false,
      error: {
        code: statusCode,
        message: body.detail || 'Erreur lors de la suppression du commentaire',
        status: 'API_ERROR'
      }
    }
  }];
}

return [{
  json: {
    success: true,
    message: 'Commentaire supprime',
    deleted: {
      recipe_id: inputData.recipe_id,
      comment_id: inputData.comment_id
    }
  }
}];
